+        // No trash pref set, so get the default if needed.
+        nsAutoString defaultTrashName;
+        if (!specialUseFolder) GetTrashFolderName(defaultTrashName);
+        for (auto trashFolder : trashFolders) {
+          if (specialUseFolder) {
